import { randomUUID } from 'node:crypto';

/** Time source. Injected so services with date rules (cutoffs, locks) are testable. */
export interface Clock {
  now(): Date;
}

export const systemClock: Clock = { now: () => new Date() };

/** Opaque record identifiers are generated by the application, not the database (portable across providers). */
export function newId(): string {
  return randomUUID();
}

/** Timestamps are stored as ISO-8601 UTC strings, e.g. 2026-10-03T04:15:00.000Z. */
export function toTimestamp(date: Date): string {
  return date.toISOString();
}
